283	bool PhysicsBody::init()
284	{
285	    do
286	    {
287	        _cpBody = cpBodyNew(_mass, _moment);
288	        internalBodySetMass(_cpBody, _mass);
289	        cpBodySetUserData(_cpBody, this);
290	        cpBodySetVelocityUpdateFunc(_cpBody, internalBodyUpdateVelocity);
291	        
292	        CC_BREAK_IF(_cpBody == nullptr);
293	        
294	        return true;
295	    } while (false);
296	    
297	    return false;
298	}
