349	void PhysicsBody::setScale(float scaleX, float scaleY)
350	{
351	    for (auto& shape : _shapes)
352	    {
353	        _area -= shape->getArea();
354	        if (!_massSetByUser)
355	            addMass(-shape->getMass());
356	        if (!_momentSetByUser)
357	            addMoment(-shape->getMoment());
358	        
359	        shape->setScale(scaleX, scaleY);
360	        
361	        _area += shape->getArea();
362	        if (!_massSetByUser)
363	            addMass(shape->getMass());
364	        if (!_momentSetByUser)
365	            addMoment(shape->getMoment());
366	    }
367	}
