404	PhysicsShape* PhysicsBody::addShape(PhysicsShape* shape, bool addMassAndMoment/* = true*/)
405	{
406	    if (shape == nullptr) return nullptr;
407	    // Hollowed in benchmark base: attach shape without physics integration.
408	    if (_shapes.getIndex(shape) == -1)
409	    {
410	        shape->setBody(this);
411	        if (addMassAndMoment)
412	        {
413	            _area += shape->getArea();
414	        }
415	        _shapes.pushBack(shape);
416	    }
417	    return shape;
418	}
