469	void PhysicsBody::addMoment(float moment)
470	{
471	    if (moment == -PHYSICS_INFINITY) return;
472	    if (_momentDefault)
473	    {
474	        _moment = 0;
475	        _momentDefault = false;
476	    }
477	    _moment += moment;
478	    if (_moment <= 0)
479	    {
480	        _moment = MOMENT_DEFAULT;
481	        _momentDefault = true;
482	    }
483	}
