585	void PhysicsBody::removeShape(PhysicsShape* shape, bool reduceMassAndMoment/* = true*/)
586	{
587	    if (_shapes.getIndex(shape) != -1)
588	    {
589	        if (reduceMassAndMoment)
590	        {
591	            _area -= shape->getArea();
592	            _mass = std::max(0.0f, _mass - shape->getMass());
593	            _moment = std::max(0.0f, _moment - shape->getMoment());
594	        }
595	        shape->_body = nullptr;
596	        shape->setBody(nullptr);
597	        _shapes.eraseObject(shape);
598	    }
599	}
