601	void PhysicsBody::removeAllShapes(bool reduceMassAndMoment/* = true*/)
602	{
603	    for (auto& child : _shapes)
604	    {
605	        PhysicsShape* shape = dynamic_cast<PhysicsShape*>(child);
606	        if (reduceMassAndMoment)
607	        {
608	            _area -= shape->getArea();
609	            _mass = std::max(0.0f, _mass - shape->getMass());
610	            _moment = std::max(0.0f, _moment - shape->getMoment());
611	        }
612	        shape->_body = nullptr;
613	        shape->setBody(nullptr);
614	    }
615	    
616	    _shapes.clear();
617	}
