void PhysicsBody::setMass(float mass)
{
    if (mass <= 0)
    {
        return;
    }

    _mass = mass;
    _massDefault = false;
    _massSetByUser = true;

    // update density
    if (_mass == PHYSICS_INFINITY)
    {
        _density = PHYSICS_INFINITY;
    }
    else
    {
        if (_area > 0)
        {
            _density = _mass / _area;
        }
        else
        {
            _density = 0;
        }
    }

    // the static body's mass and moment is always infinity
    if (_dynamic)
    {
        internalBodySetMass(_cpBody, _mass);
    }
}

void PhysicsBody::addMass(float mass)
{
    if (mass == PHYSICS_INFINITY)
    {
        _mass = PHYSICS_INFINITY;
        _massDefault = false;
        _density = PHYSICS_INFINITY;
    }
    else if (mass == -PHYSICS_INFINITY)
    {
        return;
    }
    else
    {
        if (_massDefault)
        {
            _mass = 0;
            _massDefault = false;
        }

        if (_mass + mass > 0)
        {
            _mass += mass;
        }
        else
        {
            _mass = MASS_DEFAULT;
            _massDefault = true;
        }

        if (_area > 0)
        {
            _density = _mass / _area;
        }
        else
        {
            _density = 0;
        }
    }

    // the static body's mass and moment is always infinity
    if (_dynamic)
    {
        internalBodySetMass(_cpBody, _mass);
    }
}

void PhysicsBody::addMoment(float moment)
{
    if (moment == PHYSICS_INFINITY)
    {
        // if moment is infinity, the moment of the body will be infinity
        _moment = PHYSICS_INFINITY;
        _momentDefault = false;
    }
    else if (moment == -PHYSICS_INFINITY)
    {
        return;
    }
    else
    {
        if (_momentDefault)
        {
            _moment = 0;
            _momentDefault = false;
        }

        if (_moment + moment > 0)
        {
            _moment += moment;
        }
        else
        {
            _moment = MOMENT_DEFAULT;
            _momentDefault = true;
        }
    }

    // the static body's mass and moment is always infinity
    if (_rotationEnabled && _dynamic)
    {
        cpBodySetMoment(_cpBody, _moment);
    }
}

